	for table, want := range map[string]int{"conversation_forks": forks, "api_idempotency": completions} {
		got := actualForks
		if table == "api_idempotency" {
			got = actualCompletions
		}
		if got != want {
			t.Fatalf("%s rows=%d want=%d", table, got, want)
