					t.Fatalf("EventSnapshot replay: %v", err)
				}
				assertOperatorReplaySnapshot(t, persistedSnapshot, persistedWant)
				var replayRoute events.DeliveryRoute
				for _, delivery := range persisted.Deliveries {
					if delivery.SubscriberID == agentID {
						replayRoute = delivery.Route.Normalized()
						break
					}
				}
				if replayRoute.Recipient.ID() != agentID {
					t.Fatalf("replay event is missing exact managed-agent route: %#v", persisted.Deliveries)
				}
				replayTurnID := uuid.NewString()
				replayFrame := storetest.PersistManagedAgentTurnFixture(t, ctx, storetest.ManagedAgentTurnFixture{Store: frameStore, Selected: f.store, Identity: agentIdentity, RunID: runID, SessionID: uuid.NewString(), TurnID: replayTurnID, Memory: agentmemory.Plan{Enabled: false}, Event: persistedSnapshot, DeliveryRoute: &replayRoute, DeliveryCommitted: true, ParseOK: true, CreatedAt: replayAt.Add(time.Minute), ExecutionMode: executionmode.Mock, Adapter: "mock_python"})
