	}
	conflictEvent := rpcCall(t, handler, runStartBody(runID, runStartTestBundleHash, "scan.missing", `{"topic":"medicine"}`, "idem-start"))
	if conflictEvent.Error == nil {
		t.Fatal("run.start event-change idempotency conflict error = nil")
