		t.Fatalf("run.start event-change conflict data = %#v", data)
	}
	if count := countEventsByName(t, pg, "scan.requested"); count != 1 {
		t.Fatalf("scan.requested event count after body-domain conflicts = %d, want 1", count)
	}
