func testFanInSingletonRoutePersistsExactSelectedOwnerOnBothBackends(t *testing.T) {
	t.Helper()
	repoRoot := canonicalrouting.RepoRoot(t)
	bundle, err := runtimecontracts.LoadWorkflowContractBundleWithOverrides(repoRoot, canonicalrouting.ExampleRoot(t, canonicalrouting.FanInStream), runtimecontracts.DefaultPlatformSpecFile(repoRoot))
	if err != nil {
		t.Fatalf("load canonical fan-in barrier: %v", err)
	}
	source := semanticview.Wrap(bundle)
	for _, tc := range []struct {
		name  string
		setup func(*testing.T) (fanInBarrierConformanceStore, *sql.DB)
	}{{name: "postgres", setup: func(t *testing.T) (fanInBarrierConformanceStore, *sql.DB) {
		_, db, cleanup := testutil.StartPostgres(t)
		t.Cleanup(cleanup)
		return storetest.AdmitPostgresRuntimeStore(t, db), db
	}}, {name: "sqlite", setup: func(t *testing.T) (fanInBarrierConformanceStore, *sql.DB) {
		backend := storetest.StartSQLiteRuntimeStore(t)
		return backend, storetest.DatabaseForTest(backend)
	}}} {
		t.Run(tc.name, func(t *testing.T) {
			backend, db := tc.setup(t)
			runID := uuid.NewString()
			ctx := runtimecorrelation.WithRunID(testAuthorActivityContextForBundle(context.Background(), conformanceSourceArtifactFact(t, source)), runID)
			seedFanInBarrierRun(t, ctx, backend, source, runID)
			selectedOwner := eventtest.UUID("fan-in-selected-owner-" + tc.name)
			selectedTarget := events.RouteIdentity{FlowID: "portfolio", FlowInstance: "portfolio/selected-period", EntityID: selectedOwner}.Normalized()
			seedRuntime := newFanInBarrierRuntime(t, backend, source)
			seedFanInBarrierPortfolioShell(t, ctx, seedRuntime.bus, seedRuntime.manager, source, selectedOwner)
			requireSelectedRunTargetOwner(t, ctx, backend, runID, "portfolio/selected-period", selectedOwner)
			eventID := uuid.NewString()
			sourceKey := eventtest.UUID("fan-in-operating-key-" + tc.name)
			sourceRoute := events.RouteIdentity{FlowID: "operating", FlowInstance: "operating/" + sourceKey, EntityID: eventtest.UUID("fan-in-source-owner-" + tc.name)}.Normalized()
			eventType := events.EventType(sourceRoute.FlowInstance + "/operating.reported")
			routingSource, err := events.NewConcreteTemplateInstanceRoutingSource(sourceRoute)
			if err != nil {
				t.Fatalf("create proof routing source: %v", err)
			}
			payload, err := json.Marshal(map[string]any{"operating_id": sourceKey, "period_id": "2026-Q3", "revenue": 42})
			if err != nil {
				t.Fatalf("marshal proof payload: %v", err)
			}
			root := runtimeflowidentity.Stored(source, semanticview.RootExecutionFlowID(source), runID, runID, runID, "")
			sourceInstance, err := runtimeflowidentity.KeyedChild(source, root, "operating", sourceKey)
			if err != nil {
				t.Fatal(err)
			}
			sourceInstance.EntityID = sourceRoute.EntityID
			trigger := eventtest.ExistingRunRootIngress(uuid.NewString(), "operating.report.requested", "fixture", "", payload, 0, runID, events.EventEnvelope{}, time.Now().UTC())
			if err := seedRuntime.manager.ActivateFlowInstance(runtimeeffects.WithExecutionMode(ctx, executionmode.Live), runtimepipeline.FlowInstanceActivationRequest{ContractBundle: source, Instance: sourceInstance, ConstructorInput: "operating.report.requested", ResolvedKey: sourceKey, TriggerEvent: trigger, OccurredAt: trigger.CreatedAt()}); err != nil {
				t.Fatalf("construct exact fan-in publication source: %v", err)
			}
			proofBus := newFanInBarrierRouteProofBus(t, backend, source, seedRuntime.manager)
			sink := newFanInBarrierRouteProofSink(t, ctx, proofBus, eventType)
			event := eventtest.ExistingRunRootIngressWithRoutingSource(eventID, eventType, "operating-proof", "", payload, 0, runID, events.EnvelopeForSourceRoute(events.EventEnvelope{}, sourceRoute), routingSource, time.Now().UTC())
			if sourceRoute.EntityID == selectedOwner || runtimeflowidentity.EntityID("portfolio") == selectedOwner {
				t.Fatal("proof identities must make source, path-derived, and selected owners distinguishable")
			}
			if inserted := commitFanInBarrierEnginePublication(t, ctx, backend, proofBus, event); !inserted {
				t.Fatal("initial fan-in proof publication was not inserted")
			}
			initialSettlement := requireFanInBarrierRouteProof(t, ctx, backend, db, eventID, selectedTarget)
			initialPublic := requireFanInBarrierPublicRouteProof(t, ctx, backend, eventID, selectedTarget)
			sink.requireDelivery(t, eventID, selectedTarget)
			if err := sink.close(true); err != nil {
				t.Fatalf("retire first proof sink: %v", err)
			}
			removeFanInBarrierSelectedOwner(t, ctx, backend, db, runID, selectedOwner)
			restartedBus := newFanInBarrierRouteProofBus(t, backend, source, seedRuntime.manager)
			restartedSink := newFanInBarrierRouteProofSink(t, ctx, restartedBus, eventType)
			if inserted := commitFanInBarrierEnginePublication(t, ctx, backend, restartedBus, event); inserted {
				t.Fatal("exact duplicate fan-in proof publication was inserted again")
			}
			restartedSink.requireNoDelivery(t)
			if err := restartedSink.close(false); err != nil {
				t.Fatalf("retire restarted proof sink: %v", err)
			}
			if got := requireFanInBarrierRouteProof(t, ctx, backend, db, eventID, selectedTarget); got != initialSettlement {
				t.Fatalf("duplicate route settlement changed:\ninitial=%s\nreplayed=%s", initialSettlement, got)
			}
			if got := requireFanInBarrierPublicRouteProof(t, ctx, backend, eventID, selectedTarget); got != initialPublic {
				t.Fatalf("duplicate public route projection changed:\ninitial=%s\nreplayed=%s", initialPublic, got)
			}
		})
	}
}

