			replay := func(id string) {
				view, err := reader.LoadOperatorEvent(ctx, id)
				if err != nil {
					t.Fatal(err)
				}
				event, err := view.EventSnapshot()
				if err != nil {
					t.Fatal(err)
				}
				if err := rt.bus.EngineDispatcher().DispatchPostCommit(ctx, []engine.EmitIntent{{Event: event}}); err != nil {
