	storetest.CommitSemanticEventWithRoutes(t, ctx, pg, evt, []events.DeliveryRoute{{Recipient: events.MustAgentDeliveryRecipient("agent-1"), AgentIdentity: lifecycleToken.Identity}}, runtimepipelineobligation.ScopeSubscribed)
	dockerState := filepath.Join(t.TempDir(), "fake-docker-count")
	fakeDocker := filepath.Join(t.TempDir(), "docker")
	script := `#!/bin/sh
state="$SWARM_FAKE_DOCKER_STATE"
count=0
if [ -f "$state" ]; then
  count=$(cat "$state")
fi
count=$((count + 1))
printf "%s" "$count" > "$state"
if [ "$count" -eq 1 ]; then
  printf "session not found" >&2
  exit 1
fi
printf '{"result":"ok"}'
`
	if err := os.WriteFile(fakeDocker, []byte(script), 0o755); err != nil {
		t.Fatalf("write fake docker: %v", err)
	}
	t.Setenv("SWARM_FAKE_DOCKER_STATE", dockerState)
	t.Setenv("CLAUDE_CODE_OAUTH_TOKEN", "stale-oauth-token")
	pg.SetSessionLockTTL(30 * time.Second)
	registry := runtimesessions.Registry(pg)
	bus, err := newScopedTestEventBus(t, pg, durableConformanceEventBusOptions(pg, runtimebus.EventBusOptions{}), "review.requested")
	if err != nil {
		t.Fatalf("NewEventBus: %v", err)
	}
	credentials := conformanceProviderCredentialResolver(t, "CLAUDE_CODE_OAUTH_TOKEN", "oauth-token")
	runtime, err := (runtimellm.RuntimeFactory{Cfg: &config.Config{Workspace: config.WorkspaceConfig{DockerBin: fakeDocker}, LLM: config.LLMConfig{Backend: "claude_cli", ClaudeCLI: config.ClaudeCLIConfig{Command: "claude", OutputFormat: "json"}}}, Sessions: registry, LiveSessions: pg, LockOwner: "worker-1", Workspaces: staticWorkspaceResolver{target: &runtimeworkspace.Target{Container: "swarm-agent-1", Workdir: "/workspace"}}, Conversations: pg, Events: bus, Credentials: credentials.Store, CompletionController: liveTestCompletionController(pg, pg, pg, discardCompletionSpendProjection{})}).Build()
	if err != nil {
		t.Fatalf("Build LLM runtime: %v", err)
	}
	workOwner := conformanceTestRuntimeOccurrence(t, authorActivityTestSourceArtifactFact.BundleHash())
	var deliveryClaim runtimedelivery.Claim
	newTurnContext := func(evt events.Event) context.Context {
		base := runtimeeffects.WithLifecycleToken(testAuthorActivityContext(context.Background()), lifecycleToken)
		base = worklifetime.WithProcess(base, conformanceTestProcessOwner(t))
		base = worklifetime.WithOccurrence(base, workOwner)
		base = managedConformanceExecutionContext(t, base, "cli-session-failure")
		base = agentmemory.WithExecution(base, agentmemory.Plan{Enabled: true}, lifecycleToken.Identity)
		base = runtimecorrelation.WithRunID(base, runID)
		base = runtimebus.WithInboundEvent(base, evt)
		if deliveryClaim.DeliveryID() != "" {
			base = runtimedelivery.WithClaim(base, deliveryClaim)
		}
		return runtimeactors.WithActor(base, runtimeactors.AgentConfig{ExecutionMode: "live", ID: "agent-1", Identity: lifecycleToken.Identity, Type: "stub", Memory: agentmemory.Plan{Enabled: true}, FlowPath: "support/inst-1"})
	}
	conversation := newConformanceManagedConversation(t, "agent-1", lifecycleToken.Identity, runtime)
