	conversation.Session = session
	conversation.SetToolExecutor(conformanceToolExecutor{})
	claimed, err := storetest.ClaimDelivery(ctx, pg, evt, events.DeliveryRoute{Recipient: events.MustAgentDeliveryRecipient(lifecycleToken.Identity.AgentID()), AgentIdentity: lifecycleToken.Identity})
	if err != nil {
		t.Fatalf("claim delivery before provider launch: %v", err)
	}
	deliveryClaim = claimed.Claim
	_, err = conversation.RunManaged(newTurnContext(evt), runtimeagentframe.TurnDraft{Kind: runtimeagentframe.TurnInitial, Event: evt})
	if conversation.Session == nil {
		t.Fatal("conversation did not retain the acquired session after provider failure")
	}
	session = conversation.Session
	failure, ok := runtimefailures.As(err)
	if !ok || failure.Failure.Class != runtimefailures.ClassOutcomeUncertain || failure.Failure.Detail.Code != "claude_cli_attempt_outcome_unconfirmed" || failure.Failure.Retryable {
		t.Fatalf("ContinueSession failure = %v, want nonretryable uncertain launched outcome", err)
	}
	if session.ID != originalSessionID {
		t.Fatalf("session ID rotated from stderr prose: got %q, want %q", session.ID, originalSessionID)
	}
	delivery, err := storetest.ReadPostgresAgentOneDeliverySessionStorage(ctx, pg, evt.ID())
	if err != nil {
		t.Fatalf("load delivery: %v", err)
	}
	deliveryStatus, activeSessionID := delivery.Status, delivery.ActiveSessionID
	if deliveryStatus != "in_progress" {
		t.Fatalf("delivery status = %q, want in_progress", deliveryStatus)
	}
	if activeSessionID != originalSessionID {
		t.Fatalf("delivery active_session_id = %q, want original %q", activeSessionID, originalSessionID)
	}
	sessionCount, err := storetest.CountPostgresAgentOneSessions(ctx, pg)
	if err != nil {
		t.Fatalf("count sessions: %v", err)
	}
	if sessionCount != 1 {
		t.Fatalf("session count = %d, want no prose-triggered successor", sessionCount)
	}
}

