func TestNotifyAllChildrenRuntimeConformance_MixedValidAndStaleRoutesPersistAndReplayOnBothBackends(t *testing.T) {
	for _, tc := range []struct {
		name  string
		setup func(*testing.T) (notifyAllChildrenStore, *sql.DB)
	}{{name: "postgres", setup: func(t *testing.T) (notifyAllChildrenStore, *sql.DB) {
		_, db, cleanup := testutil.StartPostgres(t)
		t.Cleanup(cleanup)
		return storetest.AdmitPostgresRuntimeStore(t, db), db
	}}, {name: "sqlite", setup: func(t *testing.T) (notifyAllChildrenStore, *sql.DB) {
		backend := storetest.StartSQLiteRuntimeStore(t)
		return backend, storetest.DatabaseForTest(backend)
	}}} {
		t.Run(tc.name, func(t *testing.T) {
			ctx := testAuthorActivityContext(context.Background())
			backend, db := tc.setup(t)
			runID := uuid.NewString()
			fixedEngineNow := time.Date(2026, time.July, 12, 12, 0, 0, 1, time.UTC)
			ctx = runtimecorrelation.WithRunID(ctx, runID)
			source := notifyallchildren.LoadSource(t, notifyallchildren.Options{})
			processTopology := newNotifyAllChildrenProcessTopology(t, testAuthorActivityContextForBundle(context.Background(), conformanceSourceArtifactFact(t, source)), backend)
			runtime := newNotifyAllChildrenRuntime(t, backend, db, source, func() time.Time {
				return fixedEngineNow
			}, notifyAllChildrenRuntimeOptions{processTopology: processTopology})
			if err := runtime.manager.Run(managedConformanceExecutionContextForBundle(t, ctx, "notify-all-children-stale-route", runtime.sourceArtifactFact)); err != nil {
				t.Fatalf("run manager: %v", err)
			}
			publishNotifyAllChildrenRunCreatingEvent(t, ctx, runtime, source, runID, "portfolio.opened", map[string]any{"portfolio_id": "portfolio-main"})
			assertNotifyAllChildrenRunPersisted(t, ctx, backend, runID)
			for _, accountID := range []string{"acct-a", "acct-b", "acct-stale"} {
				publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.account.register.requested", map[string]any{"portfolio_id": "portfolio-main", "account_id": accountID})
			}
			descriptors := notifyAllChildrenAccountDescriptors(t, ctx, backend)
			if len(descriptors) != 3 {
				dumpNotifyAllChildrenRuntimeState(t, ctx, backend)
				t.Logf("notify-all-children runtime diagnostics: %#v", runtime.diagnostics.snapshot())
				t.Fatalf("active account descriptors = %#v, want A/B/stale", descriptors)
			}
			for _, accountID := range []string{"acct-a", "acct-b", "acct-stale"} {
				if _, ok := descriptors[accountID]; !ok {
					t.Fatalf("active account descriptor %q missing from %#v", accountID, descriptors)
				}
			}
			orderedMembership := []string{"acct-b", "acct-a", "acct-b"}
			publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.membership.seeded", map[string]any{"portfolio_id": "portfolio-main", "account_ids": orderedMembership})
			orderedNotifyID := publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.notify.requested", map[string]any{"portfolio_id": "portfolio-main", "command": "ordered-duplicate"})
			orderedItems := loadNotifyAllChildrenItemEvents(t, ctx, backend, runID, orderedNotifyID)
			if len(orderedItems) != len(orderedMembership) {
				dumpNotifyAllChildrenRuntimeState(t, ctx, backend)
				t.Logf("notify-all-children runtime diagnostics: %#v", runtime.diagnostics.snapshot())
			}
			assertNotifyAllChildrenItemSequence(t, orderedItems, orderedMembership)
			assertNotifyAllChildrenContiguousItemOrdinals(t, orderedItems)
			for index, item := range orderedItems {
				routes, err := backend.ListEventDeliveryRoutes(ctx, item.ID)
				if err != nil {
					t.Fatalf("ordered item %d ListEventDeliveryRoutes(%s): %v", index, item.AccountID, err)
				}
				want := descriptors[item.AccountID]
				assertNotifyAllChildrenExactRoutes(t, routes, want)
			}
			publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.membership.seeded", map[string]any{"portfolio_id": "portfolio-main", "account_ids": []string{"acct-a", "acct-b", "acct-stale"}})
			assertNotifyAllChildrenMetadata(t, ctx, backend, "portfolio", "account_ids", []any{"acct-a", "acct-b", "acct-stale"})
			stale := descriptors["acct-stale"]
			if err := runtime.manager.DeactivateFlowInstanceModel(ctx, runtimepipeline.FlowInstanceDeactivationRequest{ContractBundle: source, Instance: runtimeflowidentity.Stored(source, notifyallchildren.ChildFlowID, stale.FlowInstance, stale.InstanceID, stale.EntityID, ""), FinalState: "active"}); err != nil {
				t.Fatalf("deactivate stale account: %v", err)
			}
			notifyID := publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.notify.requested", map[string]any{"portfolio_id": "portfolio-main", "command": "refresh"})
			itemEvents := loadNotifyAllChildrenItemEvents(t, ctx, backend, runID, notifyID)
			if len(itemEvents) != 3 {
				dumpNotifyAllChildrenRuntimeState(t, ctx, backend)
				t.Logf("notify-all-children runtime diagnostics: %#v", runtime.diagnostics.snapshot())
				t.Fatalf("fan-out item events = %#v, want exactly A/B/stale", itemEvents)
			}
			items := notifyAllChildrenItemIDsByAccount(t, itemEvents)
			for _, accountID := range []string{"acct-a", "acct-b"} {
				itemID := items[accountID]
				routes, err := backend.ListEventDeliveryRoutes(ctx, itemID)
				if err != nil {
					t.Fatalf("ListEventDeliveryRoutes(%s): %v", accountID, err)
				}
				want := descriptors[accountID]
				assertNotifyAllChildrenExactRoutes(t, routes, want)
				assertNotifyAllChildrenMetadata(t, ctx, backend, want.FlowInstance, "last_command", "refresh")
			}
			staleID := items["acct-stale"]
			if routes, err := backend.ListEventDeliveryRoutes(ctx, staleID); err != nil || len(routes) != 0 {
				t.Fatalf("stale routes = %#v err=%v, want none", routes, err)
			}
			failure := loadNotifyAllChildrenFailure(t, ctx, backend, staleID)
			if failure.Class != runtimefailures.ClassTargetUnreachable || !strings.Contains(failure.Detail.Code, "target") {
				t.Fatalf("stale failure = %#v, want platform.target_unreachable with route detail", failure)
			}
			assertNotifyAllChildrenFlowInstanceCount(t, ctx, backend, 3)
			publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.membership.seeded", map[string]any{"portfolio_id": "portfolio-main", "account_ids": []string{"acct-a"}})
			publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.notify.requested", map[string]any{"portfolio_id": "portfolio-main", "command": "newer"})
			assertNotifyAllChildrenMetadata(t, ctx, backend, descriptors["acct-a"].FlowInstance, "last_command", "newer")
			publishNotifyAllChildrenEvent(t, ctx, runtime, source, runID, "portfolio.membership.seeded", map[string]any{"portfolio_id": "portfolio-main", "account_ids": []string{"acct-b"}})
			if err := runtime.bus.WaitForQuiescence(testAuthorActivityContextForBundle(ctx, runtime.sourceArtifactFact)); err != nil {
				t.Fatalf("drain old runtime before restart: %v", err)
			}
			runtime.fanOutServing.Close()
			oldContinuations, ok := runtime.bus.DeliveryContinuationOwner().(*runtimedeliverycontinuation.Coordinator)
			if !ok {
				t.Fatal("old runtime lacks its delivery continuation owner")
			}
			if err := oldContinuations.Retire(ctx); err != nil {
				t.Fatalf("retire old delivery continuations: %v", err)
			}
			if err := runtime.manager.Shutdown(); err != nil {
				t.Fatalf("shut down old agent manager: %v", err)
			}
			runtime.workOwner.Retire()
			if _, err := runtime.workOwner.RetireAndWait(ctx); err != nil {
				t.Fatalf("join old runtime generation: %v", err)
			}
			originalA := items["acct-a"]
			deleteNotifyAllChildrenPipelineReceipt(t, ctx, backend, db, originalA)
			claimed, err := backend.PipelineObligations().ClaimEvent(ctx, originalA, runtimepipelineobligation.PurposeRecovery)
			if err != nil {
				t.Fatalf("claim original pipeline obligation: %v", err)
			}
			replay := claimed.Event
			if err := backend.PipelineObligations().Release(ctx, claimed.Claim); err != nil {
				t.Fatalf("release original pipeline obligation: %v", err)
			}
			routes, err := backend.ListEventDeliveryRoutes(ctx, originalA)
			if err != nil {
				t.Fatalf("original A persisted routes: %v", err)
			}
			assertNotifyAllChildrenExactRoutes(t, routes, descriptors["acct-a"])
			recoveryEvent := eventtest.RuntimeControl(uuid.NewString(), replay.Type(), "workflow-runtime", "", replay.Payload(), replay.ChainDepth()+1, runID, replay.ID(), replay.Envelope(), fixedEngineNow.Add(time.Second))
			storetest.CommitSemanticEventWithInitialFacts(t, ctx, backend, recoveryEvent, routes, runtimepipelineobligation.ScopeSubscribed, storetest.AcknowledgedPipelineDisposition())
			eventCountBefore := countNotifyAllChildrenItemEvents(t, ctx, backend, db, runID)
			restarted := newNotifyAllChildrenRuntime(t, backend, db, source, func() time.Time {
				return fixedEngineNow
			}, notifyAllChildrenRuntimeOptions{processTopology: processTopology, deferContinuationStart: true})
			restartCtx := testAuthorActivityContextForBundle(ctx, restarted.sourceArtifactFact)
			startup, err := restarted.manager.CanonicalizeDynamicFlowRuntimeStartupReadiness(restartCtx, restarted.sourceArtifactFact, true)
			if err != nil {
				t.Fatalf("canonicalize restarted dynamic topology: %v", err)
			}
			if err := restarted.manager.Run(managedConformanceExecutionContextForBundle(t, restartCtx, "notify-all-children-stale-route-restart", restarted.sourceArtifactFact)); err != nil {
				t.Fatalf("run restarted manager: %v", err)
			}
			if err := restarted.manager.CompleteDynamicFlowRuntimeStartupTopology(restartCtx, startup); err != nil {
				t.Fatalf("complete restarted dynamic topology: %v", err)
			}
			if _, err := restarted.manager.HydrateForStartup(restartCtx); err != nil {
				t.Fatalf("hydrate restarted manager: %v", err)
			}
			startNotifyAllChildrenDeliveryContinuations(t, ctx, backend, restarted, recoveryEvent.ID(), routes[0])
			waitNotifyAllChildrenRuntime(t, restarted, runID)
			assertNotifyAllChildrenMetadata(t, ctx, backend, descriptors["acct-a"].FlowInstance, "last_command", "refresh")
			if got := countNotifyAllChildrenItemEvents(t, ctx, backend, db, runID); got != eventCountBefore {
				t.Fatalf("item event count after replay = %d, want %d; replay must not re-expand current membership", got, eventCountBefore)
			}
			routes, err = backend.ListEventDeliveryRoutes(ctx, recoveryEvent.ID())
			if err != nil {
				t.Fatalf("recovered persisted A routes: %v", err)
			}
			assertNotifyAllChildrenExactRoutes(t, routes, descriptors["acct-a"])
		})
	}
}

