		runTelegramConnectorSupportedSurfaceRoundTrip(t, telegramConnectorSupportedSurfaceBackend{name: "sqlite", ctx: ctx, eventStore: sqliteStore, deliveryStore: sqliteStore, inboundStore: sqliteStore, inboundTarget: target, persistence: runtimepipeline.NewWorkflowPersistence(sqliteStore), runLifecycle: sqliteStore, obligations: sqliteStore.PipelineObligations(), runID: runID, entityID: entityID, flowInstance: flowInstance})
	})
}

