			if err != nil {
				t.Fatal(err)
			}
			count = 0
			for _, row := range report.EventCounts {
				if row.EventName == "ack" {
					count += row.Count
				}
			}
			if count != 1 {
				t.Fatalf("duplicate final effect: %d", count)
			}
		})
	}
}

