		credentialEnv string
		adapter       string
		model         string
		initial       string
		continuation  string
	}{{name: "anthropic", backend: llmselection.BackendAnthropic, credentialEnv: "ANTHROPIC_API_KEY", adapter: "anthropic_api", model: "claude-selected-fork", initial: `{"model":"claude-selected-fork","usage":{"input_tokens":11,"output_tokens":3},"content":[{"type":"tool_use","id":"lookup-1","name":"lookup_data","input":{"query":"status"}}]}`, continuation: `{"model":"claude-selected-fork","usage":{"input_tokens":13,"output_tokens":4},"content":[{"type":"tool_use","id":"emit-1","name":"emit_task_completed","input":{}}]}`}, {name: "openai_compatible", backend: llmselection.BackendOpenAICompatible, credentialEnv: llmselection.OpenAICompatibleCredentialEnv, adapter: "openai_compatible", model: "gpt-selected-fork", initial: `{"model":"gpt-selected-fork","choices":[{"message":{"role":"assistant","tool_calls":[{"id":"lookup-1","type":"function","function":{"name":"lookup_data","arguments":"{\"query\":\"status\"}"}}]}}],"usage":{"prompt_tokens":11,"completion_tokens":3,"total_tokens":14}}`, continuation: `{"model":"gpt-selected-fork","choices":[{"message":{"role":"assistant","content":"completed","tool_calls":[{"id":"emit-1","type":"function","function":{"name":"emit_task_completed","arguments":"{}"}}]}}],"usage":{"prompt_tokens":13,"completion_tokens":4,"total_tokens":17}}`}, {name: "openai_responses", backend: llmselection.BackendOpenAIResponses, credentialEnv: llmselection.OpenAIResponsesCredentialEnv, adapter: "openai_responses", model: "gpt-selected-fork", initial: `{"id":"resp-selected-fork-1","model":"gpt-selected-fork","output":[{"id":"lookup-1","type":"function_call","call_id":"lookup-1","name":"lookup_data","arguments":"{\"query\":\"status\"}"}],"usage":{"input_tokens":11,"output_tokens":3,"total_tokens":14}}`, continuation: `{"id":"resp-selected-fork-2","model":"gpt-selected-fork","output":[{"id":"emit-1","type":"function_call","call_id":"emit-1","name":"emit_task_completed","arguments":"{}"}],"usage":{"input_tokens":13,"output_tokens":4,"total_tokens":17}}`}}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
